class TestSplitToken:
    """Unit tests for the internal _split_token helper."""

    def test_trailing_punctuation(self):
        assert _split_token("hello,") == ["hello", ","]

    def test_leading_punctuation(self):
        assert _split_token("(word)") == ["(", "word", ")"]

    def test_contractions_stay_together(self):
        assert _split_token("don't") == ["don't"]

    def test_pure_word(self):
