class TestTokenize:
    """Tests for the public tokenize function."""

    def test_basic_sentence(self):
        tokens = tokenize("Hello world")
        assert len(tokens) == 2
        assert tokens[0].text == "Hello"
        assert tokens[1].text == "world"

    def test_punctuation_split_off(self):
        tokens = tokenize("hello, world!")
        texts = [t.text for t in tokens]
        assert "hello" in texts
        assert "," in texts
        assert "world" in texts
        assert "!" in texts

    def test_case_preserved_in_text(self):
        tokens = tokenize("Hello WORLD")
        assert tokens[0].text == "Hello"
        assert tokens[1].text == "WORLD"

    def test_lower_attribute(self):
        tokens = tokenize("Hello WORLD")
        assert tokens[0].lower == "hello"
        assert tokens[1].lower == "world"

    def test_empty_string(self):
        tokens = tokenize("")
        assert tokens == []

    def test_whitespace_only(self):
        tokens = tokenize("   \t  ")
        assert tokens == []

    def test_contractions(self):
        tokens = tokenize("don't can't won't")
        texts = [t.text for t in tokens]
        assert "don't" in texts
        assert "can't" in texts
        assert "won't" in texts

    def test_multiple_spaces(self):
        tokens = tokenize("hello   world")
        assert len(tokens) == 2

    def test_newlines_treated_as_whitespace(self):
        tokens = tokenize("hello\nworld")
        assert len(tokens) == 2

    def test_token_str(self):
        tok = Token(text="Hello", lower="hello")
        assert str(tok) == "Hello"

